CREATE TABLE firmware_packages(id BINARY(16) PRIMARY KEY,vendor VARCHAR(100) NOT NULL,model VARCHAR(100) NOT NULL,version VARCHAR(60) NOT NULL,download_url VARCHAR(1000) NOT NULL,checksum VARCHAR(128) NOT NULL,checksum_algorithm VARCHAR(20) NOT NULL,signature VARCHAR(2000),file_size_bytes BIGINT NOT NULL,active BOOLEAN NOT NULL,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_firmware_vendor_model_version UNIQUE(vendor,model,version));CREATE TABLE firmware_update_jobs(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,charger_id BINARY(16) NOT NULL,firmware_package_id BINARY(16) NOT NULL,ocpp_version VARCHAR(20) NOT NULL,status VARCHAR(30) NOT NULL,scheduled_at TIMESTAMP(6) NOT NULL,status_info VARCHAR(1000),created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_firmware_job_package FOREIGN KEY(firmware_package_id)REFERENCES firmware_packages(id));CREATE INDEX idx_firmware_jobs_tenant_created ON firmware_update_jobs(tenant_id,created_at);CREATE INDEX idx_firmware_jobs_charger ON firmware_update_jobs(charger_id);
